#include <iostream>
#include <vector>
#include <string>
#include <sstream>
#include <algorithm>

struct Point {
    std::vector<long> coords;

    Point(std::initializer_list<long> c) : coords(c) {}

    long getSumOfSquares() const {
        long sum = 0;
        for (long c : coords) {
            sum += c * c;
        }
        return sum;
    }

    long dotProduct(const Point& other) const {
        long result = 0;
        for (size_t i = 0; i < coords.size(); ++i) {
            result += coords[i] * other.coords[i];
        }
        return result;
    }

    Point subtract(const Point& other) const {
        std::vector<long> newCoords(coords.size());
        for (size_t i = 0; i < coords.size(); ++i) {
            newCoords[i] = coords[i] - other.coords[i];
        }
        return Point{newCoords[0], newCoords[1], newCoords[2], newCoords[3], newCoords[4]};
    }
};

bool isPointValid(const std::vector<Point>& points, int index) {
    const Point& p = points[index];
    int size = points.size();
    for (int j = 0; j < size; ++j) {
        if (j == index) continue;
        for (int k = 0; k < size; ++k) {
            if (k == index || k == j) continue;
            Point v1 = points[j].subtract(p);
            Point v2 = points[k].subtract(p);
            if (v1.dotProduct(v2) > 0) return false;
        }
    }
    return true;
}

int main() {
    int n;
    std::cin >> n;
    if (n > 11) {
        std::cout << 0 << "\n";
        return 0;
    }
    std::vector<Point> pts;
    for (int i = 0; i < n; ++i) {
        std::string line;
        std::getline(std::cin, line); // To consume leftover newline
        std::getline(std::cin, line);
        std::istringstream iss(line);
        long coords[5];
        for (int j = 0; j < 5; ++j) {
            iss >> coords[j];
        }
        pts.emplace_back(coords[0], coords[1], coords[2], coords[3], coords[4]);
    }
    std::vector<int> validPoints;
    for (int i = 0; i < n; ++i) {
        if (isPointValid(pts, i)) {
            validPoints.push_back(i + 1);
        }
    }
    std::cout << validPoints.size() << "\n";
    for (int v : validPoints) {
        std::cout << v << "\n";
    }
    return 0;
}

